   "newText": "def transform(grid):
    out=[row[:] for row in grid]
    n,m=len(grid),len(grid[0])
    # A marker pair indicates a color line; for each pair, use the color of
    # the object nearest the top endpoint, continuing the line through zeros.
    markers=[c for c in range(m) if grid[n-1][c]==5]
    for c in markers:
        # In training, a matching line color is attached to a nearby source
        # object in the same column or immediately adjacent columns.
        candidates=[]
        for r in range(n-1):
            for cc in range(max(0,c-1),min(m,c+2)):
                if grid[r][cc] not in (0,5): candidates.append((r,abs(cc-c),grid[r][cc]))
        color=min(candidates)[2] if candidates else 0
        for r in range(n-1):
            if grid[r][c]==0: out[r][c]=color
    return out
